"""Read one top-level section of ``integrations.yml`` without the rest of the file.

Section loaders expand ``${VAR}`` placeholders only inside the section they
own, so an unset variable in another block (for example an LLM API key while
loading the event broker) does not stop that section from loading.
"""

from __future__ import annotations

from pathlib import Path
from typing import Optional

from ruamel import yaml

from rasa.shared.exceptions import RasaException
from rasa.shared.project_structure import MANTLE_INTEGRATIONS_FILE
from rasa.shared.utils.yaml import construct_yaml_node, read_yaml_file_section_node


def read_integrations_section_node(
    project_root: str | Path, key: str, *, allow_list: bool = False
) -> Optional[yaml.Node]:
    """Return one section of ``integrations.yml`` as an unconstructed node.

    Args:
        project_root: Directory expected to contain ``integrations.yml``.
        key: Top-level key to read.
        allow_list: Accept a list value as well as a mapping.

    Returns:
        The section node, or ``None`` when the file or key is absent, or when
        the key is null.

    Raises:
        RasaException: If the file exists but its root is not a mapping, or if
            the key is present but its value has the wrong shape.
    """
    integration_file = Path(project_root) / MANTLE_INTEGRATIONS_FILE
    if not integration_file.is_file():
        return None

    section = read_yaml_file_section_node(integration_file, key)
    if section is None:
        return None
    if isinstance(section, yaml.MappingNode) or (
        allow_list and isinstance(section, yaml.SequenceNode)
    ):
        return section

    value = construct_yaml_node(
        section, expand_env_vars=False, filename=integration_file
    )
    if value is None:
        return None
    expected = "a mapping or a list" if allow_list else "a mapping"
    raise RasaException(
        f"'{key}' in '{MANTLE_INTEGRATIONS_FILE}' must be {expected}, "
        f"but got '{type(value).__name__}'."
    )
